library(visNetwork)
library(tidyverse)



Код простроения визуализации
dag_code &lt;- '
IV1 [iv1]
IV2 [iv2]
DV [dv]
MED [med]
COLL [coll]
CONF1 [conf1]
CONF2 [conf2]
IV1 -&gt; DV
IV2 -&gt; DV
IV1 -&gt; MED
MED -&gt; DV
CONF1 -&gt; IV1
CONF1 -&gt; DV
CONF2 -&gt; MED
CONF2 -&gt; DV
IV2 -&gt; COLL
DV -&gt; COLL
'

# always_visible &lt;- c("Antibiotics", "Asthma", "FEV1")

## узлы
node_lines &lt;- str_extract_all(dag_code, "\\w+\\s*\\[[^\\]]+\\]")[[1]]

nodes &lt;- tibble(raw = node_lines) %&gt;%
  mutate(
    id = str_extract(raw, "^\\w+"),
    attrs = str_extract(raw, "\\[([^\\]]+)\\]"),
    iv = grepl("iv", attrs),
    dv = grepl("dv", attrs),
    coll = grepl("coll", attrs),
    conf = grepl("conf", attrs),
    med = grepl("med", attrs),
    role = case_when(
      iv ~ "iv",
      dv ~ "dv",
      conf ~ "conf",
      coll ~ "coll",
      med ~ "med",
      TRUE ~ "third"
    ),
    color = case_when(
      iv ~ clrs$iv,
      dv ~ clrs$dv,
      conf ~ clrs$conf,
      coll ~ clrs$coll,
      med ~ clrs$med,
      TRUE ~ clrs$third
    ),
    # size = if_else(id %in% always_visible, 32, 20),
    opacity = 1.0, # по умолчанию всё видимо
    label = id,
    title = paste0("&lt;b&gt;", id, "&lt;/b&gt;&lt;br&gt;Role: ", role)
  )

## круговая раскладка
# n &lt;- nrow(nodes)
# angles &lt;- seq(0, 2 * pi, length.out = n + 1)[1:n]
# radius &lt;- 320
